# SPDX-License-Identifier: LGPL-3.0-or-later
"""Edge-graph geometry and differential-observable utilities.

The graph uses one flat, frame-major node axis.  An edge is directed from a
neighbor (``src``) to its center atom (``dst``), and its differentiable
geometry is

``edge_vec = r_src - r_dst``.

Periodic images are represented by their image displacement in ``edge_vec``
but by the local atom that owns the image in ``edge_index``.  Consequently,
force and virial reductions never expose ghost atoms to callers.
"""

from __future__ import annotations

import itertools
from dataclasses import dataclass
from typing import TYPE_CHECKING

import numpy as np

from deepmd.dpmodel.array_api import xp_add_at

if TYPE_CHECKING:
    from deepmd.dpmodel.array_api import Array


@dataclass
class NeighborGraph:
    """Edge-graph neighbor list. Node axis is flat ``N = sum(n_node)``."""

    n_node: "Array"
    """(nf,) int nodes per frame."""

    edge_index: "Array"
    """(2, E) int [src, dst]; src=neighbor, dst=center."""

    edge_vec: "Array"
    """(E, 3) float r_src-r_dst; the geometry/autograd leaf."""

    edge_mask: "Array"
    """(E,) bool real edge versus padding edge."""

    n_local: "Array | None" = None
    angle_index: "Array | None" = None
    angle_mask: "Array | None" = None


@dataclass
class GraphLayout:
    """Length policy: dynamic axes use ``None``; static backends use capacity."""

    edge_capacity: int | None = None
    angle_capacity: int | None = None
    node_capacity: int | None = None
    frame_capacity: int | None = None
    min_edges: int = 2


def _integer_array(value, name: str, ndim: int | None = None) -> np.ndarray:
    """Convert an integer-valued input without silently truncating floats."""
    array = np.asarray(value)
    if ndim is not None and array.ndim != ndim:
        raise ValueError(f"{name} must have {ndim} dimensions, got {array.shape}")
    if array.dtype.kind not in "iu":
        if array.dtype.kind != "f" or not np.all(np.isfinite(array)) or not np.all(array == np.floor(array)):
            raise ValueError(f"{name} must contain integers")
    return np.asarray(array, dtype=np.int64)


def _nonnegative_int(value, name: str) -> int:
    if isinstance(value, (bool, np.bool_)) or not isinstance(value, (int, np.integer)):
        raise ValueError(f"{name} must be a non-negative integer")
    result = int(value)
    if result < 0:
        raise ValueError(f"{name} must be a non-negative integer")
    return result


def _validate_layout(layout: GraphLayout | None) -> GraphLayout:
    if layout is None:
        return GraphLayout()
    if not isinstance(layout, GraphLayout):
        raise ValueError("layout must be a GraphLayout or None")
    _nonnegative_int(layout.min_edges, "layout.min_edges")
    for field in ("edge_capacity", "angle_capacity", "node_capacity", "frame_capacity"):
        value = getattr(layout, field)
        if value is not None:
            _nonnegative_int(value, f"layout.{field}")
    return layout


def _coordinate_batch(coord, atype) -> tuple[np.ndarray, np.ndarray]:
    """Normalize ordinary and legacy flattened coordinates to ``(nf, n, 3)``."""
    types = np.asarray(atype)
    if types.ndim == 1:
        types = types[None, :]
    elif types.ndim != 2:
        raise ValueError(f"atype must have shape (n_atom,) or (n_frame, n_atom), got {types.shape}")
    types = _integer_array(types, "atype", ndim=2)
    n_frame, n_atom = types.shape

    xyz = np.asarray(coord)
    if xyz.dtype.kind not in "iuf":
        raise ValueError("coord must contain real numbers")
    if xyz.ndim == 3:
        if xyz.shape != (n_frame, n_atom, 3):
            raise ValueError(
                f"coord shape {xyz.shape} is inconsistent with atype shape {types.shape}"
            )
    elif xyz.ndim == 2 and xyz.shape == (n_frame, n_atom * 3):
        xyz = xyz.reshape(n_frame, n_atom, 3)
    elif n_frame == 1 and xyz.ndim == 2 and xyz.shape == (n_atom, 3):
        xyz = xyz[None, :, :]
    elif n_frame == 1 and xyz.ndim == 1 and xyz.shape == (n_atom * 3,):
        xyz = xyz.reshape(1, n_atom, 3)
    else:
        raise ValueError(
            f"coord shape {xyz.shape} is inconsistent with atype shape {types.shape}"
        )
    if not np.all(np.isfinite(xyz)):
        raise ValueError("coord must contain only finite values")
    dtype = xyz.dtype if xyz.dtype.kind == "f" else np.dtype(np.float64)
    return np.asarray(xyz, dtype=dtype), types


def _cell_batch(cell, n_frame: int, coord_dtype) -> np.ndarray | None:
    if cell is None:
        return None
    cells = np.asarray(cell)
    if cells.dtype.kind not in "iuf":
        raise ValueError("cell must contain real numbers")
    if cells.ndim == 3 and cells.shape == (n_frame, 3, 3):
        pass
    elif cells.ndim == 2 and cells.shape == (n_frame, 9):
        cells = cells.reshape(n_frame, 3, 3)
    elif n_frame == 1 and cells.ndim == 2 and cells.shape == (3, 3):
        cells = cells[None, :, :]
    elif n_frame == 1 and cells.ndim == 1 and cells.shape == (9,):
        cells = cells.reshape(1, 3, 3)
    else:
        raise ValueError(f"cell must describe {n_frame} frame(s) with 3 by 3 matrices, got {cells.shape}")
    if not np.all(np.isfinite(cells)):
        raise ValueError("cell must contain only finite values")
    dtype = np.result_type(coord_dtype, cells.dtype, np.float32)
    cells = np.asarray(cells, dtype=dtype)
    # Inversion is required both for wrapping and for a finite image bound.
    try:
        inverse = np.linalg.inv(cells)
    except np.linalg.LinAlgError as exc:
        raise ValueError("cell matrices must be nonsingular") from exc
    if not np.all(np.isfinite(inverse)):
        raise ValueError("cell matrices must be nonsingular")
    return cells


def _padded_counts(n_node: np.ndarray, layout: GraphLayout) -> np.ndarray:
    n_frame = len(n_node)
    if layout.frame_capacity is not None:
        capacity = int(layout.frame_capacity)
        if capacity < n_frame:
            raise ValueError(
                f"frame capacity {capacity} is smaller than the {n_frame} input frames"
            )
        if capacity > n_frame:
            n_node = np.pad(n_node, (0, capacity - n_frame))
    total_node = int(n_node.sum())
    if layout.node_capacity is not None and int(layout.node_capacity) < total_node:
        raise ValueError(
            f"node capacity {layout.node_capacity} is smaller than the {total_node} input nodes"
        )
    return n_node


def _pack_edges(
    n_node: np.ndarray,
    edge_index: np.ndarray,
    edge_vec: np.ndarray,
    layout: GraphLayout,
) -> NeighborGraph:
    """Apply the compact-prefix edge layout and construct a graph."""
    n_edge = edge_index.shape[1]
    if layout.edge_capacity is None:
        capacity = max(n_edge, int(layout.min_edges))
    else:
        capacity = int(layout.edge_capacity)
        if capacity < n_edge:
            raise ValueError(
                f"edge capacity {capacity} is smaller than the {n_edge} physical edges"
            )
    padded_index = np.zeros((2, capacity), dtype=np.int64)
    padded_vec = np.zeros((capacity, 3), dtype=edge_vec.dtype)
    edge_mask = np.zeros(capacity, dtype=bool)
    if n_edge:
        padded_index[:, :n_edge] = edge_index
        padded_vec[:n_edge] = edge_vec
        edge_mask[:n_edge] = True
    return NeighborGraph(
        n_node=n_node,
        edge_index=padded_index,
        edge_vec=padded_vec,
        edge_mask=edge_mask,
        n_local=n_node.copy(),
    )


def build_neighbor_graph(
    coord,
    atype,
    cell,
    rcut: float,
    layout: GraphLayout | None = None,
) -> NeighborGraph:
    """Build all directed neighbor edges within ``rcut``.

    Parameters
    ----------
    coord
        Coordinates with shape ``(n_frame, n_atom, 3)`` or the legacy shape
        ``(n_frame, 3 * n_atom)``.  Unbatched one-frame forms are accepted too.
    atype
        Integer atom types with shape ``(n_frame, n_atom)``.  Negative types
        are virtual atoms: their node slots are preserved, but no physical edge
        has a virtual source or destination.
    cell
        Optional row-vector periodic cells, one ``(3, 3)`` matrix per frame.
        With a cell, all lattice images inside the cutoff are emitted and image
        sources map back to their local atom indices.
    rcut
        Positive finite cutoff.  Distances equal to the cutoff are included.
    layout
        Optional static capacity policy.  Real edges always occupy a compact
        prefix; any remaining edge slots have a false mask and zero vector.

    Notes
    -----
    The local node axis contains all input atom slots, including virtual and
    isolated atoms.  This preserves alignment of returned per-atom quantities
    with the caller's input arrays.
    """
    try:
        cutoff = float(rcut)
    except (TypeError, ValueError) as exc:
        raise ValueError("rcut must be a positive finite scalar") from exc
    if not np.isfinite(cutoff) or cutoff <= 0.0:
        raise ValueError("rcut must be a positive finite scalar")
    layout = _validate_layout(layout)
    xyz, types = _coordinate_batch(coord, atype)
    n_frame, n_atom, _ = xyz.shape
    cells = _cell_batch(cell, n_frame, xyz.dtype)
    if cells is not None:
        dtype = np.result_type(xyz.dtype, cells.dtype)
        xyz = xyz.astype(dtype, copy=False)

    n_node = _padded_counts(np.full(n_frame, n_atom, dtype=np.int64), layout)
    edges: list[tuple[int, int]] = []
    vectors: list[np.ndarray] = []
    cutoff2 = cutoff * cutoff

    for frame in range(n_frame):
        frame_offset = frame * n_atom
        valid = np.flatnonzero(types[frame] >= 0)
        if cells is None:
            frame_xyz = xyz[frame]
            for dst in valid:
                candidates = []
                for src in valid:
                    if src == dst:
                        continue
                    vector = frame_xyz[src] - frame_xyz[dst]
                    distance2 = float(np.dot(vector, vector))
                    if distance2 <= cutoff2:
                        candidates.append((distance2, int(src), vector))
                candidates.sort(key=lambda item: (item[0], item[1]))
                for _, src, vector in candidates:
                    edges.append((frame_offset + src, frame_offset + int(dst)))
                    vectors.append(vector)
            continue

        frame_cell = cells[frame]
        # Wrapping first gives a finite image range independent of how far the
        # caller's displayed coordinates lie outside the primitive cell.
        fractional = xyz[frame] @ np.linalg.inv(frame_cell)
        frame_xyz = np.mod(fractional, 1.0) @ frame_cell
        determinant = abs(float(np.linalg.det(frame_cell)))
        face_norm = np.asarray(
            [
                np.linalg.norm(np.cross(frame_cell[1], frame_cell[2])),
                np.linalg.norm(np.cross(frame_cell[2], frame_cell[0])),
                np.linalg.norm(np.cross(frame_cell[0], frame_cell[1])),
            ]
        )
        face_distance = determinant / face_norm
        if not np.all(np.isfinite(face_distance)) or np.any(face_distance <= 0.0):
            raise ValueError("cell matrices must be nonsingular")
        image_bound = np.ceil(cutoff / face_distance).astype(np.int64)
        shifts = list(
            itertools.product(
                range(-int(image_bound[0]), int(image_bound[0]) + 1),
                range(-int(image_bound[1]), int(image_bound[1]) + 1),
                range(-int(image_bound[2]), int(image_bound[2]) + 1),
            )
        )
        shifts.sort(key=lambda shift: (sum(component * component for component in shift), shift))
        shifted = [(shift, np.asarray(shift, dtype=frame_cell.dtype) @ frame_cell) for shift in shifts]
        for dst in valid:
            candidates = []
            for src in valid:
                base_vector = frame_xyz[src] - frame_xyz[dst]
                for shift, translation in shifted:
                    if src == dst and shift == (0, 0, 0):
                        continue
                    vector = base_vector + translation
                    distance2 = float(np.dot(vector, vector))
                    if distance2 <= cutoff2:
                        candidates.append((distance2, int(src), shift, vector))
            candidates.sort(key=lambda item: (item[0], item[1], item[2]))
            for _, src, _, vector in candidates:
                edges.append((frame_offset + src, frame_offset + int(dst)))
                vectors.append(vector)

    if edges:
        edge_index = np.asarray(edges, dtype=np.int64).T
        edge_vec = np.asarray(vectors, dtype=xyz.dtype).reshape(-1, 3)
    else:
        edge_index = np.zeros((2, 0), dtype=np.int64)
        edge_vec = np.zeros((0, 3), dtype=xyz.dtype)
    return _pack_edges(n_node, edge_index, edge_vec, layout)


def _extended_coordinate_batch(extended_coord, mapping: np.ndarray) -> np.ndarray:
    n_frame, n_all = mapping.shape
    xyz = np.asarray(extended_coord)
    if xyz.dtype.kind not in "iuf":
        raise ValueError("extended_coord must contain real numbers")
    if xyz.ndim == 3 and xyz.shape == (n_frame, n_all, 3):
        pass
    elif xyz.ndim == 2 and xyz.shape == (n_frame, n_all * 3):
        xyz = xyz.reshape(n_frame, n_all, 3)
    elif n_frame == 1 and xyz.ndim == 2 and xyz.shape == (n_all, 3):
        xyz = xyz[None, :, :]
    elif n_frame == 1 and xyz.ndim == 1 and xyz.shape == (n_all * 3,):
        xyz = xyz.reshape(1, n_all, 3)
    else:
        raise ValueError(
            f"extended_coord shape {xyz.shape} is inconsistent with mapping shape {mapping.shape}"
        )
    if not np.all(np.isfinite(xyz)):
        raise ValueError("extended_coord must contain only finite values")
    dtype = xyz.dtype if xyz.dtype.kind == "f" else np.dtype(np.float64)
    return np.asarray(xyz, dtype=dtype)


def from_dense_quartet(
    extended_coord,
    nlist,
    mapping,
    layout: GraphLayout | None = None,
) -> NeighborGraph:
    """Convert a legacy extended-coordinate/dense-list tuple into a graph.

    ``nlist[frame, center, slot]`` indexes ``extended_coord``.  ``mapping``
    maps each extended (possibly periodic-image) index back to a local source
    atom.  Negative neighbor-list entries are padding and are removed before
    edge packing, so their indices are never dereferenced.
    """
    layout = _validate_layout(layout)
    owner = np.asarray(mapping)
    if owner.ndim == 1:
        owner = owner[None, :]
    elif owner.ndim != 2:
        raise ValueError(f"mapping must have shape (n_frame, n_extended), got {owner.shape}")
    owner = _integer_array(owner, "mapping", ndim=2)
    xyz = _extended_coordinate_batch(extended_coord, owner)

    dense = np.asarray(nlist)
    if dense.ndim == 2 and owner.shape[0] == 1:
        dense = dense[None, :, :]
    elif dense.ndim != 3:
        raise ValueError(f"nlist must have shape (n_frame, n_local, n_neighbor), got {dense.shape}")
    dense = _integer_array(dense, "nlist", ndim=3)
    n_frame, n_local, _ = dense.shape
    if n_frame != owner.shape[0]:
        raise ValueError(
            f"nlist has {n_frame} frames but mapping has {owner.shape[0]} frames"
        )
    n_all = owner.shape[1]
    if n_local > n_all:
        raise ValueError("extended_coord must contain the local center coordinates first")

    n_node = _padded_counts(np.full(n_frame, n_local, dtype=np.int64), layout)
    edges: list[tuple[int, int]] = []
    vectors: list[np.ndarray] = []
    for frame in range(n_frame):
        frame_offset = frame * n_local
        for dst in range(n_local):
            for extended_src in dense[frame, dst]:
                extended_src = int(extended_src)
                if extended_src < 0:
                    continue
                if extended_src >= n_all:
                    raise ValueError(
                        f"nlist index {extended_src} is outside the {n_all} extended atoms"
                    )
                src = int(owner[frame, extended_src])
                if src < 0 or src >= n_local:
                    raise ValueError(
                        f"mapping owner {src} is outside the {n_local} local atoms"
                    )
                edges.append((frame_offset + src, frame_offset + dst))
                vectors.append(xyz[frame, extended_src] - xyz[frame, dst])

    if edges:
        edge_index = np.asarray(edges, dtype=np.int64).T
        edge_vec = np.asarray(vectors, dtype=xyz.dtype).reshape(-1, 3)
    else:
        edge_index = np.zeros((2, 0), dtype=np.int64)
        edge_vec = np.zeros((0, 3), dtype=xyz.dtype)
    return _pack_edges(n_node, edge_index, edge_vec, layout)


def node_validity_mask(n_node, node_capacity: int | None = None) -> np.ndarray:
    """Return the compact-prefix mask implied by per-frame node counts."""
    counts = _integer_array(n_node, "n_node", ndim=1)
    if np.any(counts < 0):
        raise ValueError("n_node must contain non-negative counts")
    total = int(counts.sum())
    capacity = total if node_capacity is None else _nonnegative_int(node_capacity, "node_capacity")
    if capacity < total:
        raise ValueError(f"node capacity {capacity} is smaller than the {total} physical nodes")
    mask = np.zeros(capacity, dtype=bool)
    mask[:total] = True
    return mask


def _segment_inputs(data, segment_ids, num_segments: int) -> tuple[np.ndarray, np.ndarray, int]:
    values = np.asarray(data)
    if values.ndim == 0:
        raise ValueError("data must have a leading item axis")
    ids = _integer_array(segment_ids, "segment_ids", ndim=1)
    if values.shape[0] != ids.shape[0]:
        raise ValueError(
            f"data has {values.shape[0]} items but segment_ids has {ids.shape[0]}"
        )
    count = _nonnegative_int(num_segments, "num_segments")
    if np.any(ids < 0) or np.any(ids >= count):
        raise ValueError("segment_ids must be in [0, num_segments)")
    return values, ids, count


def segment_sum(data, segment_ids, num_segments: int) -> np.ndarray:
    """Sum a leading item axis into arbitrary, possibly empty, segments."""
    values, ids, count = _segment_inputs(data, segment_ids, num_segments)
    output = np.zeros((count,) + values.shape[1:], dtype=values.dtype)
    return xp_add_at(output, ids, values)


def segment_mean(data, segment_ids, num_segments: int) -> np.ndarray:
    """Mean a leading item axis, returning zero for empty segments."""
    values, ids, count = _segment_inputs(data, segment_ids, num_segments)
    sums = segment_sum(values, ids, count)
    output_dtype = sums.dtype if sums.dtype.kind in "fc" else np.result_type(sums.dtype, np.float64)
    output = np.zeros(sums.shape, dtype=output_dtype)
    item_count = np.zeros(count, dtype=np.int64)
    xp_add_at(item_count, ids, np.ones(len(ids), dtype=np.int64))
    denominator = item_count.reshape((count,) + (1,) * (values.ndim - 1))
    np.divide(sums, denominator, out=output, where=denominator != 0)
    return output


def edge_force_virial(
    edge_gradient,
    edge_vec,
    edge_index,
    edge_mask,
    n_node,
    node_capacity: int | None = None,
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Assemble forces and virials from edge-vector energy derivatives.

    For ``g = dE / d(edge_vec)`` and ``edge_vec = r_src - r_dst``, this uses

    ``F_k = sum(dst == k, g) - sum(src == k, g)``

    and the explicit tensor convention

    ``edge_virial[a, b] = -g[a] * edge_vec[b]``.

    A complete edge virial is attributed to its local source atom.  Masked
    guard edges are filtered before their indices or values are used.  The
    returned arrays have shapes ``(node_capacity, 3)``,
    ``(node_capacity, 3, 3)``, and ``(n_frame, 3, 3)`` respectively.
    """
    gradient = np.asarray(edge_gradient)
    vector = np.asarray(edge_vec)
    index = np.asarray(edge_index)
    mask = np.asarray(edge_mask, dtype=bool)
    if gradient.ndim != 2 or gradient.shape[1:] != (3,):
        raise ValueError(f"edge_gradient must have shape (n_edge, 3), got {gradient.shape}")
    if vector.shape != gradient.shape:
        raise ValueError(
            f"edge_vec shape {vector.shape} is inconsistent with edge_gradient shape {gradient.shape}"
        )
    n_edge = gradient.shape[0]
    if index.shape != (2, n_edge):
        raise ValueError(f"edge_index must have shape (2, {n_edge}), got {index.shape}")
    index = _integer_array(index, "edge_index", ndim=2)
    if mask.shape != (n_edge,):
        raise ValueError(f"edge_mask must have shape ({n_edge},), got {mask.shape}")
    counts = _integer_array(n_node, "n_node", ndim=1)
    if np.any(counts < 0):
        raise ValueError("n_node must contain non-negative counts")
    total_node = int(counts.sum())
    capacity = total_node if node_capacity is None else _nonnegative_int(node_capacity, "node_capacity")
    if capacity < total_node:
        raise ValueError(
            f"node capacity {capacity} is smaller than the {total_node} physical nodes"
        )


    real_index = index[:, mask]
    if np.any(real_index < 0) or np.any(real_index >= total_node):
        raise ValueError("a physical edge index is outside the nodes described by n_node")
    dtype = np.result_type(gradient.dtype, vector.dtype)
    if dtype.kind not in "fc":
        dtype = np.dtype(np.float64)
    real_gradient = np.asarray(gradient[mask], dtype=dtype)
    real_vector = np.asarray(vector[mask], dtype=dtype)
    force = np.zeros((capacity, 3), dtype=dtype)
    atom_virial = np.zeros((capacity, 3, 3), dtype=dtype)
    frame_virial = np.zeros((len(counts), 3, 3), dtype=dtype)
    if real_index.shape[1] == 0:
        return force, atom_virial, frame_virial

    src, dst = real_index
    node_frame = np.repeat(np.arange(len(counts), dtype=np.int64), counts)
    src_frame = node_frame[src]
    if np.any(src_frame != node_frame[dst]):
        raise ValueError("physical edges may not connect nodes from different frames")

    xp_add_at(force, dst, real_gradient)
    xp_add_at(force, src, -real_gradient)
    # Axis order is deliberate: gradient component first, displacement second.
    edge_virial = -real_gradient[:, :, None] * real_vector[:, None, :]
    xp_add_at(atom_virial, src, edge_virial)
    xp_add_at(frame_virial, src_frame, edge_virial)
    return force, atom_virial, frame_virial
